from collections import Counter

def predict_from_block_mode():
    out = []
    for block_row in range(3):
        start_r = block_row * 4
        result_col = []
        for col in range(6):
            # Collect all non-zero values in this block for this column
            vals = []
            for r in range(start_r, start_r + 4):
                if test_input[r][col] != 0:
                    vals.append(test_input[r][col])

            if not vals:
                result_col.append(0)
            else:
                counter = Counter(vals)
                # Get mode, use first one if tie
                mode = counter.most_common(1)[0][0]
                result_col.append(mode)
        out.append(result_col)
    return out

