# Find best match for each test column
def find_best_match(test_sig, d1_sigs, d1_out_rows):
    """Find D1 column with closest signature, return predicted output"""
    min_dist = float('inf')
    best_col = None
    for dc_idx, sig in enumerate(d1_sigs):
        # Hamming-like distance ignoring None
        dist = 0
        for i, (t_v, d_v) in enumerate(zip(test_sig, sig)):
            if t_v is not None and d_v is not None and t_v != d_v:
                dist += 1
            elif t_v is None and d_v is not None:
                dist += 1
            elif t_v is not None and d_v is None:
                dist += 1
        if dist < min_dist:
            min_dist = dist
            best_col = dc_idx
    if best_col is not None:
        return [d1_out_rows[0][best_col], d1_out_rows[1][best_col], d1_out_rows[2][best_col]], min_dist
    return None, min_dist

